(()=>{var e=Array.from(document.querySelectorAll("dialog")),c=document.querySelectorAll("button[data-index]");c.forEach((t,l)=>{t.addEventListener("click",()=>{e[l]?.showModal(),e[l]?.focus()})}),e.forEach((t,l)=>{let d=t.querySelector("button[data-close]"),h=t.querySelector('button[data-nav="prev"]'),u=t.querySelector('button[data-nav="next"]');d?.addEventListener("click",()=>t.close()),h?.addEventListener("click",()=>{t.close();let o=e[(l-1+e.length)%e.length];o?.showModal(),o?.focus()}),u?.addEventListener("click",()=>{t.close();let o=e[(l+1)%e.length];o?.showModal(),o?.focus()}),t.addEventListener("keydown",o=>{if(o.key==="ArrowRight"){o.preventDefault(),t.close();let n=e[(l+1)%e.length];n?.showModal(),n?.focus()}else if(o.key==="ArrowLeft"){o.preventDefault(),t.close();let n=e[(l-1+e.length)%e.length];n?.showModal(),n?.focus()}});let r=0,a=0;t.addEventListener("touchstart",o=>{o.touches.length>1||(r=o.touches[0].screenX)}),t.addEventListener("touchend",o=>{if(o.changedTouches.length>1)return;a=o.changedTouches[0].screenX;let n=a-r;if(Math.abs(n)<50)return;t.close();let s=n>0?e[(l-1+e.length)%e.length]:e[(l+1)%e.length];s?.showModal(),s?.focus()})}),window.addEventListener("click",t=>{e.forEach(l=>{t.target===l&&l.close()})})})();
